import{_ as o,c as t,o as r,aj as l}from"./chunks/framework.D26WZD1w.js";const p=JSON.parse('{"title":"🏥 寒暑假異地就醫操作流程","description":"","frontmatter":{"comment":false},"headers":[],"relativePath":"zh-yue/workflows/medical.md","filePath":"zh-yue/workflows/medical.md","lastUpdated":1785552058000}'),i={name:"zh-yue/workflows/medical.md"};function s(n,a,e,h,c,d){return r(),t("div",null,a[0]||(a[0]=[l('<h1 id="🏥-寒暑假異地就醫操作流程" tabindex="-1">🏥 寒暑假異地就醫操作流程 <a class="header-anchor" href="#🏥-寒暑假異地就醫操作流程" aria-label="Permalink to &quot;🏥 寒暑假異地就醫操作流程&quot;">​</a></h1><div class="danger custom-block"><p class="custom-block-title">提示</p><p>本流程適用於需要喺珠海市以外地區就醫嘅 BNBU 學生。請跟住以下步驟完成異地就醫備案。</p></div><h2 id="前置步驟" tabindex="-1">前置步驟 <a class="header-anchor" href="#前置步驟" aria-label="Permalink to &quot;前置步驟&quot;">​</a></h2><p>如果揀線上操作，可以加 <strong>BNBU 醫療及健康教育中心</strong> 微信：<strong>a13928025919</strong> 如果揀線下操作，請去 <strong>北師香港浸會大學醫務室</strong> 攞資料表格</p><h2 id="第一步-定點" tabindex="-1">第一步：定點 <a class="header-anchor" href="#第一步-定點" aria-label="Permalink to &quot;第一步：定點&quot;">​</a></h2><p>喺微信完成門診選點登記，將學校醫務室設為定點醫療機構</p><h3 id="選點步驟" tabindex="-1">選點步驟 <a class="header-anchor" href="#選點步驟" aria-label="Permalink to &quot;選點步驟&quot;">​</a></h3><ol><li>開 <strong>微信小程式</strong></li><li>搜尋並進入 <strong>珠海社保掌上辦</strong></li><li>揀 <strong>醫療生育保險</strong></li><li>撳 <strong>門診選點登記</strong></li><li>揀 <strong>新增選點</strong></li><li>揀 <strong>門診統籌選點</strong></li><li>揀區域：<strong>高新技術產業開發區</strong></li><li>揀機構：<strong>北師香港浸會大學醫務室</strong></li></ol><h2 id="第二步-攞同填備案表" tabindex="-1">第二步：攞同填備案表 <a class="header-anchor" href="#第二步-攞同填備案表" aria-label="Permalink to &quot;第二步：攞同填備案表&quot;">​</a></h2><ol><li>線上微信/線下攞 <strong>異地就醫備案表</strong></li><li>老實填寫表格內容</li><li>將填好嘅備案表 <strong>交返醫療及健康教育中心蓋章</strong></li></ol><div class="info custom-block"><p class="custom-block-title">注意</p><p>蓋章流程通常要等 3-5 個工作天，請耐心等待。蓋章完成後，醫務室會通知你攞返備案表</p></div><h2 id="第三步-異地申請" tabindex="-1">第三步：異地申請 <a class="header-anchor" href="#第三步-異地申請" aria-label="Permalink to &quot;第三步：異地申請&quot;">​</a></h2><p>喺微信小程式完成異地就醫備案申請。</p><h3 id="備案步驟" tabindex="-1">備案步驟 <a class="header-anchor" href="#備案步驟" aria-label="Permalink to &quot;備案步驟&quot;">​</a></h3><ol><li>開 <strong>微信小程式</strong></li><li>搜尋並進入 <strong>珠海社保掌上辦</strong></li><li>揀 <strong>醫療生育保險</strong></li><li>撳 <strong>異地就醫備案</strong></li><li>填寫 <strong>電話號碼</strong></li><li>揀備案類型：<strong>異地長期居住（含在校大學生）</strong></li><li>填寫就醫地：<strong>轉去嘅地址</strong>（即係你要就醫嘅城市/醫院）</li><li>填寫參保地：<strong>學校地址</strong></li><li>揀材料類型：<strong>長期居住認定類型</strong></li><li>撳 <strong>下一步</strong></li><li><strong>拍照上傳</strong> 第二步已經蓋咗章嘅異地就醫備案表</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>通常 10 分鐘內會完成審核</p></div><h2 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to &quot;常見問題&quot;">​</a></h2><h3 id="q-備案需要幾耐先審核通過" tabindex="-1">Q：備案需要幾耐先審核通過？ <a class="header-anchor" href="#q-備案需要幾耐先審核通過" aria-label="Permalink to &quot;Q：備案需要幾耐先審核通過？&quot;">​</a></h3><p>A：一般情況下，提交備案後 1-3 個工作天內可以完成審核</p><h3 id="q-點解需要異地就醫備案" tabindex="-1">Q: 點解需要異地就醫備案？ <a class="header-anchor" href="#q-點解需要異地就醫備案" aria-label="Permalink to &quot;Q: 點解需要異地就醫備案？&quot;">​</a></h3><p>中國嘅<strong>基本醫療保險</strong>實行屬地管理，即係參保人嘅醫保關係綁定喺參保地（珠海）。當你需要喺珠海以外嘅城市就醫嗰陣，就屬於「異地就醫」。</p><p>未辦理備案嘅，無辦法喺異地定點醫療機構直接刷醫保卡/刷醫保碼結算，要<strong>先自己畀錢墊住全部醫療費用</strong>，再返去珠海參保地申請手工報銷</p><p>未經備案嘅異地就醫，報銷比例通常會<strong>大幅降低</strong>，個人負擔加重，而且要自己收集同寄返大量票據、病歷等材料，審批週期長</p><h3 id="q-辦理備案後嘅好處" tabindex="-1">Q: 辦理備案後嘅好處 <a class="header-anchor" href="#q-辦理備案後嘅好處" aria-label="Permalink to &quot;Q: 辦理備案後嘅好處&quot;">​</a></h3><ul><li><strong>直接結算</strong>：喺異地定點醫療機構刷醫保卡/醫保碼就可以完成費用結算，只係要畀自己嗰份</li><li><strong>報銷比例正常</strong>：實行「就醫地目錄、參保地政策」，即係藥品同診療項目跟就醫地規定，報銷比例照珠海參保地政策正常執行</li></ul><h3 id="q-使用流程" tabindex="-1">Q: 使用流程 <a class="header-anchor" href="#q-使用流程" aria-label="Permalink to &quot;Q: 使用流程&quot;">​</a></h3><p>開微信「我的醫保憑證」小程式，交費嗰陣話畀佢知同出示二維碼；或者出示社保卡</p>',27)]))}const u=o(i,[["render",s]]);export{p as __pageData,u as default};
